/* ── helpers ── */
function b64ToBytes(b64){const bin=atob(b64);const u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);return u;}
function buildGeometry(p,bytes){
  const {min,rng}=META;const nv=p.nv;const dv=new DataView(bytes.buffer);
  const pos=new Float32Array(nv*3);
  for(let i=0;i<nv*3;i++){const q=dv.getUint16(p.po+i*2,true);const a=i%3;pos[i]=q/65535*rng[a]+min[a];}
  const uv=new Float32Array(nv*2);
  for(let i=0;i<nv*2;i++)uv[i]=dv.getUint16(p.uo+i*2,true)/65535;
  let idx;
  if(p.itype===2){idx=new Uint16Array(p.ni);for(let i=0;i<p.ni;i++)idx[i]=dv.getUint16(p.io+i*2,true);}
  else{idx=new Uint32Array(p.ni);for(let i=0;i<p.ni;i++)idx[i]=dv.getUint32(p.io+i*4,true);}
  const g=new THREE.BufferGeometry();
  g.setAttribute('position',new THREE.BufferAttribute(pos,3));
  g.setAttribute('uv',new THREE.BufferAttribute(uv,2));
  g.setIndex(new THREE.BufferAttribute(idx,1));g.computeVertexNormals();return g;
}

