function MileageField({current,onCommit}){
  const [draft,setDraft]=useState(String(current||0));
  const [editing,setEditing]=useState(false);
  // keep draft in sync when not actively editing
  useEffect(()=>{ if(!editing) setDraft(String(current||0)); },[current,editing]);
  const dirty=editing && draft!==String(current||0) && draft!=="";
  const commit=()=>{ const n=parseInt(draft,10); if(!isNaN(n)){ onCommit(n); } setEditing(false); };
  return(
    <div style={{marginBottom:16}}>
      <div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:8,color:"#3a3428",letterSpacing:3,marginBottom:5}}>CURRENT MILEAGE</div>
      <div style={{display:"flex",gap:8}}>
        <input type="number" inputMode="numeric" value={draft}
          onFocus={()=>setEditing(true)}
          onChange={e=>{setEditing(true);setDraft(e.target.value);}}
          onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();commit();e.target.blur();}}}
          style={{flex:1,background:"#090807",border:"1px solid #1e1c18",color:BONE,
            fontFamily:"'Share Tech Mono',monospace",fontSize:12,padding:"8px 10px",outline:"none",boxSizing:"border-box"}}/>
        <button onClick={commit} disabled={!dirty}
          style={{fontFamily:"'Share Tech Mono',monospace",fontSize:10,letterSpacing:2,
            padding:"0 16px",cursor:dirty?"pointer":"default",
            background:dirty?GOLD:"#15120e",color:dirty?"#0a0805":"#4a4438",
            border:`1px solid ${dirty?GOLD:"#2a2520"}`,
            boxShadow:dirty?`0 0 8px ${GOLD}66`:"none",transition:"all .15s"}}>SET</button>
      </div>
      <div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:8,color:"#2a2520",marginTop:3}}>Type the full number, then tap SET (or Enter)</div>
    </div>
  );
}
